package com.troday.api.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.troday.api.dto.ApiResponseDto;
import com.troday.api.entity.*;
import com.troday.api.repository.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.transaction.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime; import java.util.*;

@Service
public class RoommateService {
 @org.springframework.beans.factory.annotation.Autowired private DomainSupport domain;
    @org.springframework.beans.factory.annotation.Autowired private MessagingService messaging;
    private final AccountService accounts; private final RoommateProfileRepository profiles; private final LifestyleCriterionRepository criteria;
    private final ProfileLifestyleRepository lifestyles; private final RoommateRequestRepository requests;
    public RoommateService(AccountService a, RoommateProfileRepository p, LifestyleCriterionRepository c, ProfileLifestyleRepository l, RoommateRequestRepository q){accounts=a;profiles=p;criteria=c;lifestyles=l;requests=q;}
    public ApiResponseDto<?> myProfile(HttpServletRequest r){return ok("GET",profileData(my(r)));}
    @Transactional public ApiResponseDto<?> saveProfile(HttpServletRequest r,JsonNode b){Long tenant=accounts.authenticatedUserId(r);if(b==null||!b.isObject())throw bad("JSON request là bắt buộc");domain.jdbc.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",tenant);RoommateProfile p=profiles.findByTenantId(tenant).orElseGet(RoommateProfile::new);if(p.getId()!=null)domain.expectedVersion(r,b,"profileVersion",p.getProfileVersion());if(b.hasNonNull("profileVersion")&&!Objects.equals(p.getProfileVersion(),b.get("profileVersion").asLong()))throw conflict("Phiên bản hồ sơ đã thay đổi");applyProfile(p,b,tenant);p.setProfileVersion(Optional.ofNullable(p.getProfileVersion()).orElse(1L)+(p.getId()==null?0:1));return ok("PUT",profileData(profiles.save(p)));}
    public ApiResponseDto<?> publicProfile(HttpServletRequest r,Long id){accounts.authenticatedUserId(r);return ok("GET",publicProfileData(profiles.findById(id).filter(p->p.isActive()||p.getTenantId().equals(accounts.authenticatedUserId(r))||domain.exists("SELECT id FROM roommate_requests WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?)",p.getTenantId(),accounts.authenticatedUserId(r),accounts.authenticatedUserId(r),p.getTenantId())).orElseThrow(()->notFound("Không tìm thấy hồ sơ"))));}
    public ApiResponseDto<?> criterionList(HttpServletRequest r){accounts.authenticatedUserId(r);return ok("GET",criteria.findByActiveTrue().stream().map(this::criterionData).toList());}
    public ApiResponseDto<?> myLifestyles(HttpServletRequest r){return ok("GET",lifestyles.findByProfileId(my(r).getId()).stream().map(this::lifestyleData).toList());}
    @Transactional public ApiResponseDto<?> saveLifestyles(HttpServletRequest r,JsonNode b){RoommateProfile p=my(r);if(b==null||!b.has("criteria")||!b.get("criteria").isArray())throw bad("criteria là bắt buộc");lifestyles.deleteByProfileId(p.getId());lifestyles.flush();Set<Long> seen=new HashSet<>();List<ProfileLifestyle> out=new ArrayList<>();for(JsonNode n:b.get("criteria")){Long cid=longValue(n,"criterionId");LifestyleCriterion c=criteria.findById(cid).filter(LifestyleCriterion::isActive).orElseThrow(()->bad("criterionId không hợp lệ"));if(!seen.add(cid))throw bad("Tiêu chí bị trùng");JsonNode self=n.get("selfValue"),pref=n.get("preferredValue");validateValue(c,self);validateValue(c,pref);if((self==null||self.isNull())&&(pref==null||pref.isNull()))throw bad("Mỗi tiêu chí cần selfValue hoặc preferredValue");int imp=n.path("importance").asInt(1);if(imp<0||imp>5)throw bad("importance phải từ 0 đến 5");ProfileLifestyle x=new ProfileLifestyle();x.setProfileId(p.getId());x.setCriterionId(c.getId());x.setSelfValue(self==null||self.isNull()?null:self.toString());x.setPreferredValue(pref==null||pref.isNull()?null:pref.toString());x.setMandatory(n.path("isMandatory").asBoolean(false));x.setImportance(imp);out.add(lifestyles.save(x));}p.setProfileVersion(Optional.ofNullable(p.getProfileVersion()).orElse(1L)+1);profiles.save(p);return ok("PUT",Map.of("profileVersion",p.getProfileVersion(),"items",out.stream().map(this::lifestyleData).toList()));}
    public ApiResponseDto<?> matches(HttpServletRequest r){RoommateProfile mine=my(r);List<Map<String,Object>> out=profiles.findByActiveTrue().stream().filter(p->!p.getId().equals(mine.getId())).filter(p->mandatoryCompatible(mine,p)&&mandatoryCompatible(p,mine)).map(p->Map.<String,Object>of("profile",publicProfileData(p),"score",score(mine,p),"algorithmVersion","preview-v1","explanations",List.of("Đã lọc yêu cầu bắt buộc; điểm gợi ý đang thử nghiệm, chưa có trọng số nghiệp vụ được duyệt"))).sorted((a,b)->Integer.compare((Integer)b.get("score"),(Integer)a.get("score"))).toList();return ok("GET",out);}
    @Transactional public ApiResponseDto<?> adminCreateCriterion(HttpServletRequest r,JsonNode b){accounts.requireAdminId(r);LifestyleCriterion c=new LifestyleCriterion();applyCriterion(c,b);return ok("POST",criterionData(criteria.save(c)));}
    @Transactional public ApiResponseDto<?> adminUpdateCriterion(HttpServletRequest r,Long id,JsonNode b){accounts.requireAdminId(r);LifestyleCriterion c=criteria.findById(id).orElseThrow(()->notFound("Không tìm thấy tiêu chí"));if(b.hasNonNull("valueType")&&!b.get("valueType").asText().equals(c.getValueType())&&domain.exists("SELECT id FROM profile_lifestyles WHERE criterion_id=?",id))throw conflict("Tạo tiêu chí mới để giữ nghĩa lịch sử");com.fasterxml.jackson.databind.node.ObjectNode merged=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(criterionData(c));b.fields().forEachRemaining(e->merged.set(e.getKey(),e.getValue()));applyCriterion(c,merged);return ok("PATCH",criterionData(criteria.save(c)));}
    public ApiResponseDto<?> requestList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String direction=r.getParameter("direction"),status=r.getParameter("status");List<RoommateRequest> all=requests.findBySenderIdOrReceiverIdOrderByIdDesc(me,me);List<RoommateRequest> f=all.stream().filter(x->status==null||status.equals(x.getStatus())).filter(x->direction==null||(direction.equals("incoming")?x.getReceiverId().equals(me):x.getSenderId().equals(me))).toList();long incoming=all.stream().filter(x->x.getReceiverId().equals(me)).count(),outgoing=all.stream().filter(x->x.getSenderId().equals(me)).count();return ok("GET",Map.of("items",f.stream().map(this::requestData).toList(),"counts",Map.of("incoming",incoming,"outgoing",outgoing)));}
    @Transactional public ApiResponseDto<?> sendRequest(HttpServletRequest r,JsonNode b){Long sender=accounts.authenticatedUserId(r);if(b==null||!b.hasNonNull("receiverId"))throw bad("receiverId là bắt buộc");Long receiver=b.get("receiverId").asLong();if(sender.equals(receiver))throw bad("Không thể gửi lời mời cho chính mình");String scenario=text(b,"scenario");if(!Set.of("SEARCH_TOGETHER","JOIN_SYSTEM_ROOM","JOIN_EXTERNAL_HOME").contains(scenario))throw bad("scenario không hợp lệ");requireActiveProfile(sender);requireActiveProfile(receiver);if(openPair(sender,receiver))throw conflict("Hai người đã có kết nối đang mở");RoommateRequest x=new RoommateRequest();x.setSenderId(sender);x.setReceiverId(receiver);x.setScenario(scenario);if(b.hasNonNull("targetContractId")){Long cid=b.get("targetContractId").asLong();if(!domain.representative(cid,sender)&&!domain.representative(cid,receiver))throw forbidden("Một trong hai bên phải là đại diện phòng");x.setTargetContractId(cid);}x.setMessage(text(b,"message"));return ok("POST",requestData(requests.save(x)));}
    @Transactional public ApiResponseDto<?> respond(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);domain.jdbc.queryForList("SELECT id FROM roommate_requests WHERE id=? FOR UPDATE",id);RoommateRequest x=request(id);if(!x.getReceiverId().equals(me))throw forbidden("Chỉ người nhận mới được phản hồi");if(!"PENDING".equals(x.getStatus()))throw conflict("Lời mời không còn chờ xử lý");String d=text(b,"decision");if(!Set.of("ACCEPT","REJECT").contains(d))throw bad("decision phải là ACCEPT hoặc REJECT");x.setStatus("ACCEPT".equals(d)?"ACCEPTED":"REJECTED");x.setRespondedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));Map<String,Object> result=new LinkedHashMap<>();result.put("request",requestData(requests.save(x)));result.put("conversationId","ACCEPTED".equals(x.getStatus())?((Map<?,?>)messaging.roommateConversation(r,id).data()).get("id"):null);return ok("POST",result);}
    @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);RoommateRequest x=request(id);if(!x.getSenderId().equals(me))throw forbidden("Chỉ người gửi mới được hủy");if(!"PENDING".equals(x.getStatus()))throw conflict("Lời mời không còn chờ xử lý");x.setStatus("CANCELLED");return ok("POST",requestData(requests.save(x)));}
    @Transactional public ApiResponseDto<?> end(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);domain.jdbc.queryForList("SELECT id FROM roommate_requests WHERE id=? FOR UPDATE",id);RoommateRequest x=request(id);if(!x.getSenderId().equals(me)&&!x.getReceiverId().equals(me))throw forbidden("Không có quyền kết thúc kết nối");if(!"ACCEPTED".equals(x.getStatus())||x.getEndedAt()!=null)throw conflict("Kết nối đã kết thúc hoặc chưa được chấp nhận");x.setEndedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));x.setEndReason(text(b,"reason"));return ok("POST",requestData(requests.save(x)));}
    private RoommateProfile my(HttpServletRequest r){Long id=accounts.authenticatedUserId(r);return profiles.findByTenantId(id).orElseThrow(()->notFound("Chưa tạo hồ sơ ở ghép"));}
    private void applyProfile(RoommateProfile p,JsonNode b,Long tenant){String h=text(b,"housingStatus");if(!Set.of("NO_ACCOMMODATION","IN_SYSTEM","EXTERNAL").contains(h))throw bad("housingStatus không hợp lệ");if(!b.hasNonNull("availableFrom"))throw bad("availableFrom là bắt buộc");try{p.setAvailableFrom(LocalDate.parse(text(b,"availableFrom")));}catch(Exception e){throw bad("availableFrom không hợp lệ");}p.setTenantId(tenant);p.setHousingStatus(h);List<Long> active=domain.jdbc.queryForList("SELECT id FROM room_tenants WHERE tenant_id=? AND status='ACTIVE'",Long.class,tenant);if(!active.isEmpty()){h="IN_SYSTEM";p.setHousingStatus(h);p.setCurrentRoomTenantId(active.get(0));}else{if("IN_SYSTEM".equals(h))throw bad("Không có lượt cư trú ACTIVE của bạn");p.setCurrentRoomTenantId(null);}p.setExternalContext("EXTERNAL".equals(h)?text(b,"externalContext"):null);p.setBudgetMin(decimal(b,"budgetMin"));p.setBudgetMax(decimal(b,"budgetMax"));p.setPreferredLocation(text(b,"preferredLocation"));p.setPreferredGender(text(b,"preferredGender"));p.setActive(b.path("active").asBoolean(false));if("IN_SYSTEM".equals(h)&&p.getCurrentRoomTenantId()==null)throw bad("IN_SYSTEM cần currentRoomTenantId");if(!"IN_SYSTEM".equals(h)&&p.getCurrentRoomTenantId()!=null)throw bad("Chỉ IN_SYSTEM mới có currentRoomTenantId");if(p.getBudgetMin()!=null&&p.getBudgetMin().signum()<0||p.getBudgetMax()!=null&&p.getBudgetMax().signum()<0)throw bad("Ngân sách không được âm");if(p.getBudgetMin()!=null&&p.getBudgetMax()!=null&&p.getBudgetMax().compareTo(p.getBudgetMin())<0)throw bad("budgetMax phải lớn hơn budgetMin");}
    private void validateValue(LifestyleCriterion c,JsonNode value){if(value==null||value.isNull())return;boolean valid=switch(c.getValueType()){case "BOOLEAN"->value.isBoolean();case "NUMBER"->value.isNumber();case "TIME"->value.isTextual()&&value.asText().matches("([01][0-9]|2[0-3]):[0-5][0-9]");case "RANGE"->value.isArray()&&value.size()==2&&value.get(0).isNumber()&&value.get(1).isNumber()&&value.get(0).decimalValue().compareTo(value.get(1).decimalValue())<=0;case "CATEGORY"->value.isTextual();default->false;};if(!valid)throw bad("Giá trị không đúng kiểu tiêu chí "+c.getCode());if("CATEGORY".equals(c.getValueType())&&c.getAllowedValues()!=null){try{JsonNode allowed=new com.fasterxml.jackson.databind.ObjectMapper().readTree(c.getAllowedValues());boolean found=false;for(JsonNode v:allowed)if(v.equals(value))found=true;if(!found)throw bad("Giá trị ngoài danh mục cho phép");}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw bad("Danh mục tiêu chí không hợp lệ");}}}
    private void applyCriterion(LifestyleCriterion c,JsonNode b){String code=text(b,"code"),name=text(b,"name"),cat=text(b,"category"),type=text(b,"valueType");if(code.isBlank()||name.isBlank()||cat.isBlank()||!Set.of("BOOLEAN","NUMBER","CATEGORY","TIME","RANGE").contains(type))throw bad("Thông tin tiêu chí không hợp lệ");c.setCode(code);c.setName(name);c.setCategory(cat);c.setValueType(type);if(b.has("allowedValues"))c.setAllowedValues(b.get("allowedValues").toString());if(b.has("active"))c.setActive(b.get("active").asBoolean());}
    private boolean mandatoryCompatible(RoommateProfile preferences,RoommateProfile candidate){Map<Long,ProfileLifestyle> values=new HashMap<>();for(ProfileLifestyle row:lifestyles.findByProfileId(candidate.getId()))values.put(row.getCriterionId(),row);for(ProfileLifestyle pref:lifestyles.findByProfileId(preferences.getId()))if(pref.isMandatory()&&pref.getPreferredValue()!=null){ProfileLifestyle value=values.get(pref.getCriterionId());if(value==null||value.getSelfValue()==null)return false;try{var mapper=new com.fasterxml.jackson.databind.ObjectMapper();JsonNode wanted=mapper.readTree(pref.getPreferredValue()),actual=mapper.readTree(value.getSelfValue());boolean matches=wanted.isArray()&&wanted.size()==2&&wanted.get(0).isNumber()&&wanted.get(1).isNumber()&&actual.isNumber()?actual.decimalValue().compareTo(wanted.get(0).decimalValue())>=0&&actual.decimalValue().compareTo(wanted.get(1).decimalValue())<=0:wanted.equals(actual);if(!matches)return false;}catch(Exception e){throw conflict("Tiêu chí lưu trước đây cần được cập nhật về đúng kiểu");}}return true;}
    private int score(RoommateProfile a,RoommateProfile b){int s=0;if(Objects.equals(a.getHousingStatus(),b.getHousingStatus()))s+=30;if(overlap(a.getBudgetMin(),a.getBudgetMax(),b.getBudgetMin(),b.getBudgetMax()))s+=40;if(a.getPreferredLocation()!=null&&a.getPreferredLocation().equalsIgnoreCase(b.getPreferredLocation()))s+=30;return s;}
    private boolean overlap(BigDecimal a,BigDecimal b,BigDecimal c,BigDecimal d){return a==null||b==null||c==null||d==null||a.compareTo(d)<=0&&c.compareTo(b)<=0;}
    private boolean openPair(Long a,Long b){return requests.findBySenderIdOrReceiverIdOrderByIdDesc(a,a).stream().anyMatch(x->(x.getSenderId().equals(b)||x.getReceiverId().equals(b))&&("PENDING".equals(x.getStatus())||"ACCEPTED".equals(x.getStatus())&&x.getEndedAt()==null));}
    private void requireActiveProfile(Long id){profiles.findByTenantId(id).filter(RoommateProfile::isActive).orElseThrow(()->bad("Hai bên phải có hồ sơ ở ghép đang hoạt động"));}
    private RoommateRequest request(Long id){return requests.findById(id).orElseThrow(()->notFound("Không tìm thấy lời mời"));}
    private Map<String,Object> profileData(RoommateProfile p){Map<String,Object> m=new LinkedHashMap<>(publicProfileData(p));m.put("tenantId",p.getTenantId());m.put("profileVersion",p.getProfileVersion());m.put("currentRoomTenantId",p.getCurrentRoomTenantId());m.put("externalContext",p.getExternalContext());return m;}
    private Map<String,Object> publicProfileData(RoommateProfile p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("tenantId",p.getTenantId());m.put("housingStatus",p.getHousingStatus());m.put("availableFrom",p.getAvailableFrom());m.put("budgetMin",p.getBudgetMin());m.put("budgetMax",p.getBudgetMax());m.put("preferredLocation",p.getPreferredLocation());m.put("preferredGender",p.getPreferredGender());m.put("active",p.isActive());if("IN_SYSTEM".equals(p.getHousingStatus()))m.put("targetContractId",domain.jdbc.queryForList("SELECT contract_id FROM room_tenants WHERE id=? AND tenant_id=? AND status='ACTIVE'",Long.class,p.getCurrentRoomTenantId(),p.getTenantId()).stream().findFirst().orElse(null));return m;}
    private Map<String,Object> criterionData(LifestyleCriterion c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("code",c.getCode());m.put("name",c.getName());m.put("category",c.getCategory());m.put("valueType",c.getValueType());m.put("allowedValues",c.getAllowedValues());m.put("active",c.isActive());return m;}
    private Map<String,Object> lifestyleData(ProfileLifestyle x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("criterionId",x.getCriterionId());m.put("selfValue",x.getSelfValue());m.put("preferredValue",x.getPreferredValue());m.put("isMandatory",x.isMandatory());m.put("importance",x.getImportance());return m;}
    private Map<String,Object> requestData(RoommateRequest x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("senderId",x.getSenderId());m.put("receiverId",x.getReceiverId());m.put("scenario",x.getScenario());m.put("status",x.getStatus());m.put("message",Objects.toString(x.getMessage(),""));m.put("endedAt",x.getEndedAt());m.put("endReason",x.getEndReason());return m;}
    private BigDecimal decimal(JsonNode b,String k){if(!b.hasNonNull(k))return null;try{return new BigDecimal(b.get(k).asText());}catch(Exception e){throw bad(k+" không hợp lệ");}} private Long longValue(JsonNode b,String k){if(!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();} private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}
    private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
